import{_ as e,o as t,c as a,a2 as i}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"ADR-0006 — Go 1.26 e modulo tools/ per gli strumenti di sviluppo","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0006-go-toolchain-and-tools-module.md","filePath":"adr/0006-go-toolchain-and-tools-module.md"}'),d={name:"adr/0006-go-toolchain-and-tools-module.md"};function l(n,o,c,s,r,g){return t(),a("div",null,[...o[0]||(o[0]=[i('<h1 id="adr-0006-—-go-1-26-e-modulo-tools-per-gli-strumenti-di-sviluppo" tabindex="-1">ADR-0006 — Go 1.26 e modulo <code>tools/</code> per gli strumenti di sviluppo <a class="header-anchor" href="#adr-0006-—-go-1-26-e-modulo-tools-per-gli-strumenti-di-sviluppo" aria-label="Permalink to &quot;ADR-0006 — Go 1.26 e modulo `tools/` per gli strumenti di sviluppo&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Data</strong></td><td>2026-10-23</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§4.5 (toolchain, generazione codice)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Lo spec chiede &quot;Go ≥ versione stabile corrente&quot; e <code>make gen</code> con oapi-codegen, buf, sqlc, protoc. Aggiungere i tool con <code>tool</code> directive nel <code>go.mod</code> del servizio cloud trascinava nel modulo applicativo centinaia di dipendenze indirette (sqlc porta driver ClickHouse, Azure, TiDB…), inquinando <code>govulncheck</code> e la supply chain. sqlc 1.31 e buf 1.75 richiedono Go ≥ 1.26.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ul><li><strong>Go 1.26</strong> come versione di linguaggio in tutti i moduli (<code>go 1.26</code>); il toolchain viene scaricato automaticamente da <code>GOTOOLCHAIN=auto</code>.</li><li>Tutti i tool (oapi-codegen, sqlc, goose, buf, golangci-lint, govulncheck, protoc-gen-go, protoc-gen-go-grpc) sono pinnati con <code>tool</code> directive in <strong><code>tools/go.mod</code></strong>, modulo separato <strong>fuori da <code>go.work</code></strong>; <code>make tools</code> esegue <code>cd tools &amp;&amp; GOWORK=off go install tool</code>. <code>protobuf</code> è fissato alla pseudo-versione richiesta da buf.</li><li>I moduli applicativi non hanno dipendenze da tool.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong><code>tool</code> directive nel modulo cloud</strong> — scartata per l&#39;inquinamento delle dipendenze descritto sopra.</li><li><strong>Versioni dei tool solo nel Makefile</strong> — scartata: non verificabili da <code>go mod verify</code>, nessun lockfile.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>La CI usa <code>tools/go.mod</code> come <code>go-version-file</code>. Aggiornare un tool = <code>cd tools &amp;&amp; GOWORK=off go get -tool &lt;pkg&gt;@&lt;ver&gt;</code>.</p><h2 id="aggiornamento" tabindex="-1">Aggiornamento <a class="header-anchor" href="#aggiornamento" aria-label="Permalink to &quot;Aggiornamento&quot;">​</a></h2><p>Il toolchain è passato a <strong>Go 1.27.3</strong> (<code>go.work</code>, i moduli, <code>tools/</code>, immagini Docker, CI), anche per le correzioni della libreria standard che <code>govulncheck</code> segnalava sulla 1.26.0; i test sono rimasti verdi. Le decisioni di questo ADR restano valide. Il 2026-11-11 è passato a <strong>Go 1.27.4</strong> per GO-2026-6859 (<code>net/http</code>, segnalata da <code>govulncheck</code> su 1.27.3).</p><p><strong>Wails CLI (2026-11).</strong> La CLI di Wails non è in <code>tools/go.mod</code>: la sua versione è quella della libreria in <code>apps/desktop/go.mod</code> (oggi v2.17.0; dal 2026-11-11 il client è su Wails v3.1.0 e il percorso è quello di <a href="./0051-wails-v3.html">ADR-0051</a>: <code>scripts/install-wails.sh</code> installa <code>wails3</code>, usato solo su Windows e dal watcher di <code>task dev-desktop</code>), unica fonte di verità. <code>scripts/install-wails.sh</code> la legge da lì e installa <code>github.com/wailsapp/wails/v2/cmd/wails@&lt;versione&gt;</code> con il Go del repository, senza più sostituire <code>golang.org/x/tools</code> (la v2.17 compila con Go 1.27 così com&#39;è pubblicata); <code>--check</code> blocca <code>task gen-wails</code>, <code>dev-desktop</code> e <code>build-desktop</code> se la CLI installata è di un&#39;altra versione, e <code>wails dev</code>/<code>wails build</code> girano con <code>-nosyncgomod</code>.</p>',13)])])}const m=e(d,[["render",l]]);export{p as __pageData,m as default};
